import React, { useState, useEffect } from "react";

function App() {
  const [produit, setProduit] = useState("");
  const [quantite, setQuantite] = useState(1);
  const [prix, setPrix] = useState(0);
  const [ventes, setVentes] = useState([]);
  const [message, setMessage] = useState("");

  // ✅ Charger l'historique au démarrage
  useEffect(() => {
    const ventesStockees = localStorage.getItem("ventes");
    if (ventesStockees) {
      setVentes(JSON.parse(ventesStockees));
    }
  }, []);

  // ✅ Enregistrer une nouvelle vente
  const envoyerVente = async () => {
    if (!produit || quantite <= 0 || prix <= 0) {
      setMessage("❌ Veuillez remplir tous les champs correctement");
      return;
    }

    const nouvelleVente = {
      id: Date.now(),
      produit,
      quantite: parseInt(quantite),
      prix: parseFloat(prix),
      date: new Date().toLocaleString("fr-FR"),
      montantTotal: quantite * prix
    };

    try {
      // 📊 Envoyer à Google Sheets
      const response = await fetch("VOTRE_URL_APPS_SCRIPT", {
        method: "POST",
        body: JSON.stringify({
          produit: nouvelleVente.produit,
          quantite: nouvelleVente.quantite,
          prix: nouvelleVente.prix,
          date: nouvelleVente.date,
          montantTotal: nouvelleVente.montantTotal,
          action: "ajouter_vente"
        })
      });

      if (response.ok) {
        // ✅ Ajouter à l'historique local
        const nouvellesVentes = [...ventes, nouvelleVente];
        setVentes(nouvellesVentes);

        // 💾 Sauvegarder dans localStorage
        localStorage.setItem("ventes", JSON.stringify(nouvellesVentes));

        // Réinitialiser le formulaire
        setProduit("");
        setQuantite(1);
        setPrix(0);
        setMessage("✅ Vente enregistrée avec succès!");

        // Effacer le message après 3 secondes
        setTimeout(() => setMessage(""), 3000);
      } else {
        setMessage("❌ Erreur lors de l'envoi à Google Sheets");
      }
    } catch (err) {
      console.error("Erreur :", err);
      // Même en cas d'erreur réseau, sauvegarder localement
      const nouvellesVentes = [...ventes, nouvelleVente];
      setVentes(nouvellesVentes);
      localStorage.setItem("ventes", JSON.stringify(nouvellesVentes));
      setMessage("⚠️ Sauvegardé localement (Google Sheets indisponible)");
      setTimeout(() => setMessage(""), 3000);
    }
  };

  // ✅ Supprimer une vente
  const supprimerVente = (id) => {
    const nouvellesVentes = ventes.filter(v => v.id !== id);
    setVentes(nouvellesVentes);
    localStorage.setItem("ventes", JSON.stringify(nouvellesVentes));
    setMessage("🗑️ Vente supprimée");
    setTimeout(() => setMessage(""), 2000);
  };

  // ✅ Exporter les données
  const exporterDonnees = () => {
    const json = JSON.stringify(ventes, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `ventes_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
  };

  // Calculer les totaux
  const totalVentes = ventes.reduce((acc, v) => acc + v.montantTotal, 0);

  return (
    <div style={styles.container}>
      <div style={styles.formulaire}>
        <h1>📊 Gestion des Ventes</h1>

        <div style={styles.formGroup}>
          <label>Produit</label>
          <input
            type="text"
            placeholder="Nom du produit"
            value={produit}
            onChange={e => setProduit(e.target.value)}
            style={styles.input}
          />
        </div>

        <div style={styles.formRow}>
          <div style={styles.formGroup}>
            <label>Quantité</label>
            <input
              type="number"
              placeholder="Qté"
              value={quantite}
              onChange={e => setQuantite(e.target.value)}
              min="1"
              style={styles.input}
            />
          </div>
          <div style={styles.formGroup}>
            <label>Prix unitaire (€)</label>
            <input
              type="number"
              placeholder="Prix"
              value={prix}
              onChange={e => setPrix(e.target.value)}
              step="0.01"
              min="0"
              style={styles.input}
            />
          </div>
        </div>

        {message && <div style={styles.message}>{message}</div>}

        <button onClick={envoyerVente} style={styles.buttonPrimary}>
          ✅ Enregistrer la vente
        </button>
      </div>

      {/* 📋 HISTORIQUE */}
      <div style={styles.historique}>
        <div style={styles.headerHistorique}>
          <h2>📋 Historique ({ventes.length})</h2>
          <div>
            <button onClick={exporterDonnees} style={styles.buttonSecondary}>
              ⬇️ Exporter
            </button>
          </div>
        </div>

        {ventes.length === 0 ? (
          <p style={styles.vide}>Aucune vente enregistrée</p>
        ) : (
          <>
            <table style={styles.table}>
              <thead>
                <tr style={styles.tableHeader}>
                  <th>Date</th>
                  <th>Produit</th>
                  <th>Qté</th>
                  <th>Prix</th>
                  <th>Total</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {ventes.map((vente) => (
                  <tr key={vente.id} style={styles.tableRow}>
                    <td>{vente.date}</td>
                    <td style={styles.bold}>{vente.produit}</td>
                    <td>{vente.quantite}</td>
                    <td>{vente.prix.toFixed(2)} €</td>
                    <td style={styles.montantTotal}>
                      {vente.montantTotal.toFixed(2)} €
                    </td>
                    <td>
                      <button
                        onClick={() => supprimerVente(vente.id)}
                        style={styles.buttonDelete}
                      >
                        🗑️
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div style={styles.total}>
              <strong>Total général : {totalVentes.toFixed(2)} €</strong>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

